/* Diagrams: PD() draws vector shapes taken from the official PDFs; PG() draws coordinate grids. */
function PD(o,label){const col=c=>c==='k'?'var(--ink)':c==='n'?'none':c;let h='';for(const [k,d] of o.g){const [f,s,w]=k.split('|');h+=`<path d="${d}" fill="${col(f)}" stroke="${col(s)}" stroke-width="${w||0}" stroke-linecap="round" stroke-linejoin="round"/>`;}
 for(const [x,y,fs,t] of o.t)h+=`<text x="${x}" y="${y}" font-size="${fs}" fill="var(--ink)" font-family="Times New Roman,serif">${t}</text>`;
 return `<div class="ppfig"><svg viewBox="0 0 ${o.w} ${o.h}" role="img" aria-label="${label||'Diagram from the paper'}" style="max-width:${Math.min(560,o.w*1.6)}px">${h}</svg></div>`;}
// grid: x/y ranges, extra items: ['poly',[[x,y],...]], ['line',[x1,y1],[x2,y2]], ['pt',[x,y],label]
function PG(xr,yr,items=[],opt={}){const u=opt.u||26,pad=28,[x0,x1]=xr,[y0,y1]=yr;const W=(x1-x0)*u+pad*2,H=(y1-y0)*u+pad*2;const X=x=>pad+(x-x0)*u,Y=y=>pad+(y1-y)*u;let h='';
 for(let x=x0;x<=x1;x++)h+=`<line x1="${X(x)}" y1="${Y(y0)}" x2="${X(x)}" y2="${Y(y1)}" stroke="var(--line)" stroke-width="1"/>`;for(let y=y0;y<=y1;y++)h+=`<line x1="${X(x0)}" y1="${Y(y)}" x2="${X(x1)}" y2="${Y(y)}" stroke="var(--line)" stroke-width="1"/>`;
 if(!opt.noax){ const ax=Math.min(Math.max(0,x0),x1),ay=Math.min(Math.max(0,y0),y1);h+=`<line x1="${X(x0)}" y1="${Y(ay)}" x2="${X(x1)+12}" y2="${Y(ay)}" stroke="var(--ink)" stroke-width="1.8"/><line x1="${X(ax)}" y1="${Y(y0)}" x2="${X(ax)}" y2="${Y(y1)-12}" stroke="var(--ink)" stroke-width="1.8"/>`;
 for(let x=x0;x<=x1;x+=(opt.xs||1))if(x!==ax||opt.zero)h+=`<text x="${X(x)}" y="${Y(ay)+16}" text-anchor="middle" font-size="12" fill="var(--ink)">${x<0?'–'+(-x):x}</text>`;for(let y=y0;y<=y1;y+=(opt.ys||1))if(y!==ay)h+=`<text x="${X(ax)-6}" y="${Y(y)+4}" text-anchor="end" font-size="12" fill="var(--ink)">${y<0?'–'+(-y):y}</text>`;
 h+=`<text x="${X(ax)-5}" y="${x0<ax&&y0<ay?Y(ay)-5:Y(ay)+16}" text-anchor="end" font-size="12" fill="var(--ink)">0</text><text x="${X(x1)+16}" y="${Y(ay)+4}" font-size="13" font-style="italic" fill="var(--ink)">${opt.xl||'x'}</text><text x="${X(ax)+6}" y="${Y(y1)-14}" font-size="13" font-style="italic" fill="var(--ink)">${opt.yl||'y'}</text>`;}
 for(const it of items){if(it[0]==='poly')h+=`<polygon points="${it[1].map(p=>X(p[0])+','+Y(p[1])).join(' ')}" fill="${it[2]||'rgba(183,137,147,.25)'}" stroke="var(--ink)" stroke-width="2"/>`;else if(it[0]==='line')h+=`<line x1="${X(it[1][0])}" y1="${Y(it[1][1])}" x2="${X(it[2][0])}" y2="${Y(it[2][1])}" stroke="var(--ink)" stroke-width="2.4"/>`;else if(it[0]==='txt')h+=`<text x="${X(it[1][0])}" y="${Y(it[1][1])+5}" text-anchor="middle" font-size="14" font-weight="700" fill="var(--ink)">${it[2]}</text>`;else if(it[0]==='pt')h+=`<circle cx="${X(it[1][0])}" cy="${Y(it[1][1])}" r="3.5" fill="var(--ink)"/>${it[2]?`<text x="${X(it[1][0])+6}" y="${Y(it[1][1])-6}" font-size="13" fill="var(--ink)">${it[2]}</text>`:''}`;}
 return `<div class="ppfig"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${opt.label||'Coordinate grid'}" style="max-width:${Math.min(560,W*1.2)}px">${h}</svg></div>`;}
