   const poly=(S,col)=>`<polygon class="fadein" points="${ptsStr(S)}" fill="${col}" opacity=".5" stroke="${COL.espresso}" stroke-width="1.5"/>`;const cen=S=>[(S[0][0]+S[2][0])/2,(S[0][1]+S[2][1])/2];
